def best_circular_selection(values, k):
    n = len(values)
    if k == 0:
        return 0
    if k < 0 or k > n or (n >= 2 and k > n // 2):
        raise ValueError(f"Cannot select {k} non-adjacent elements from {n} circular elements.")
    if n == 1:
        return values[0]

    NEG_INF = -10**18

    def best_linear(arr, target_k):
        if target_k == 0:
            return 0
        m = len(arr)
        dp = [0] * (m + 1)
        for j in range(1, target_k + 1):
            new_dp = [NEG_INF] * (m + 1)
            cur_best = NEG_INF
            if j == 1:
                for idx in range(m):
                    v = arr[idx]
                    if v > cur_best:
                        cur_best = v
                    new_dp[idx + 1] = cur_best
            else:
                start = 2 * j - 2
                for idx in range(start, m):
                    cand = dp[idx - 1] + arr[idx]
                    if cand > cur_best:
                        cur_best = cand
                    new_dp[idx + 1] = cur_best
            dp = new_dp
        return dp[m]

    # Case 1: index 0 is not selected -> choose k from values[1:]
    without_first = best_linear(values[1:], k)
    # Case 2: index 0 is selected -> indices 1 and n-1 are forbidden -> choose k-1 from values[2:n-1]
    with_first = values[0] + best_linear(values[2:n - 1], k - 1)

    return max(without_first, with_first)

