def max_sessions(intervals: list[tuple[int, int]], gap: int) -> int:
    if not intervals:
        return 0

    sorted_intervals = sorted(intervals, key=itemgetter(1))
    count = 0
    next_available = sorted_intervals[0][0]

    for start, end in sorted_intervals:
        if start >= next_available:
            count += 1
            next_available = end + gap

    return count

def smallest_balanced(s: str) -> str:
    n = len(s)
    if n % 2 != 0:
        raise ValueError("Cannot balance a string of odd length.")

    half = n // 2
    fixed_open = s.count("(")
    fixed_close = s.count(")")
    if fixed_open > half or fixed_close > half:
        raise ValueError("No valid balanced replacement exists.")

    need_open = half - fixed_open
    res = []
    balance = 0

    for ch in s:
        if ch == "(":
            res.append("(")
            balance += 1
        elif ch == ")":
            res.append(")")
            balance -= 1
        else:  # ch == "?"
            if need_open > 0:
                res.append("(")
                need_open -= 1
                balance += 1
            else:
                res.append(")")
                balance -= 1

        if balance < 0:
            raise ValueError("No valid balanced replacement exists.")

    return "".join(res)

def longest_spaced_repeat(s: str, gap: int) -> int:
    n = len(s)
    best = 0
    for d in range(n - 1, gap, -1):
        limit = d - gap
        if limit <= best:
            break
        cur = 0
        for a, b in zip(s, s[d:]):
            if a == b:
                cur += 1
                if cur > best:
                    if cur >= limit:
                        best = limit
                        break
                    best = cur
            else:
                cur = 0
    return best

def min_insertions(s: str, allowed) -> int:
    n = len(s)
    if n <= 1:
        return 0

    allowed_set = set(allowed)
    inf = n + 1  # Any valid solution requires at most n - 1 insertions
    dp = [0] * n

    for i in range(n - 2, -1, -1):
        si = s[i]
        si_allowed = si in allowed_set
        prev_diag = 0  # dp[i + 1][i] == 0

        for j in range(i + 1, n):
            temp = dp[j]  # dp[i + 1][j]
            if si == s[j]:
                dp[j] = prev_diag
            else:
                best = inf
                if si_allowed and dp[j] + 1 < best:
                    best = dp[j] + 1
                if s[j] in allowed_set and dp[j - 1] + 1 < best:
                    best = dp[j - 1] + 1
                dp[j] = best
            prev_diag = temp

    return -1 if dp[n - 1] >= inf else dp[n - 1]

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)

    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visited:
            return
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in visited:
            visit(node)
    return order

import re

_AMOUNT_RE = re.compile(r"\A([0-9]+)(?:\.([0-9]{1,2}))?\Z")


def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if not isinstance(amount, str):
            raise ValueError("amount must be a string")

        match = _AMOUNT_RE.fullmatch(amount)
        if match is None:
            raise ValueError(f"invalid amount format: {amount!r}")

        dollars_str, cents_str = match.groups()
        cents = int(dollars_str) * 100 + int((cents_str or "").ljust(2, "0"))
        if cents <= 0:
            raise ValueError("amount must be positive")

        sender = tx["from"]
        receiver = tx["to"]
        balances[sender] = balances.get(sender, 0) - cents
        balances[receiver] = balances.get(receiver, 0) + cents

    return balances

import functools


def memoize(func):
    cache = {}

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            wrapper.hits += 1
            return cache[key]
        wrapper.misses += 1
        result = func(*args, **kwargs)
        cache[key] = result
        return result

    wrapper.hits = 0
    wrapper.misses = 0
    return wrapper

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for start, delete, _ in ordered:
        if start < 0 or delete < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        curr = ordered[i]
        if curr[0] == prev[0] or curr[0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")

    result = []
    pos = 0
    for start, delete, insert in ordered:
        result.extend(lines[pos:start])
        result.extend(insert)
        pos = start + delete
    result.extend(lines[pos:])
    return result

