class CountingBag:
    """A multiset (bag) of hashable items with deterministic most-common ordering."""

    def __init__(self, items=None) -> None:
        self._counts: dict = {}
        self._total: int = 0
        if items is not None:
            for item in items:
                self.add(item)

    def add(self, item) -> int:
        new_count = self._counts.get(item, 0) + 1
        self._counts[item] = new_count
        self._total += 1
        return new_count

    def discard(self, item) -> bool:
        current = self._counts.get(item)
        if current is None:
            return False
        if current == 1:
            del self._counts[item]
        else:
            self._counts[item] = current - 1
        self._total -= 1
        return True

    def count(self, item) -> int:
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        return self._total

    def distinct(self) -> int:
        return len(self._counts)

    def most_common(self, k: int) -> list:
        if k < 0:
            raise ValueError("k must be non-negative")
        n = len(self._counts)
        if k == 0 or n == 0:
            return []
        if k < n // 4:
            top = heapq.nsmallest(
                k,
                enumerate(self._counts.items()),
                key=lambda entry: (-entry[1][1], entry[0]),
            )
            return [item_count for _, item_count in top]
        return sorted(self._counts.items(), key=lambda kv: -kv[1])[:k]

