class TTLCache:
    """Fixed-capacity LRU cache with per-entry TTL driven by an explicit logical clock."""

    def __init__(self, capacity):
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._capacity = capacity
        self._entries = OrderedDict()  # key -> (value, expires_at, token)
        self._heap = []                # (expires_at, token, key)
        self._next_token = 0

        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now):
        while self._heap and self._heap[0][0] <= now:
            _, token, key = heapq.heappop(self._heap)
            entry = self._entries.get(key)
            if entry is not None and entry[2] == token:
                del self._entries[key]
                self._expirations += 1

    def _compact_heap_if_needed(self):
        if len(self._heap) > max(16, 2 * len(self._entries)):
            self._heap = [
                (entry[1], entry[2], key)
                for key, entry in self._entries.items()
                if entry[1] is not None
            ]
            heapq.heapify(self._heap)

    def put(self, key, value, now, ttl=None) -> None:
        if ttl is not None and (isinstance(ttl, bool) or ttl <= 0):
            raise ValueError("ttl must be positive or None")

        self._purge(now)

        if key in self._entries:
            self._entries.move_to_end(key)
        elif len(self._entries) >= self._capacity:
            self._entries.popitem(last=False)
            self._evictions += 1

        expires_at = None if ttl is None else now + ttl
        token = self._next_token
        self._next_token += 1

        self._entries[key] = (value, expires_at, token)
        if expires_at is not None:
            heapq.heappush(self._heap, (expires_at, token, key))
            self._compact_heap_if_needed()

    def get(self, key, now):
        self._purge(now)

        entry = self._entries.get(key)
        if entry is None:
            self._misses += 1
            return None

        self._hits += 1
        self._entries.move_to_end(key)
        return entry[0]

    def stats(self) -> dict:
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self) -> int:
        return len(self._entries)

