class Leaderboard:
    _BUCKET_LIMIT = 1024

    def __init__(self) -> None:
        self._players: dict[object, tuple[int, int]] = {}
        self._buckets: list[list[tuple[int, int, object]]] = []
        self._maxes: list[tuple[int, int, object]] = []
        self._seq = 0

    def _insert(self, item: tuple[int, int, object]) -> None:
        key = (item[0], item[1])
        if not self._buckets:
            self._buckets.append([item])
            self._maxes.append(item)
            return

        b_idx = bisect_left(self._maxes, key)
        if b_idx == len(self._buckets):
            b_idx -= 1
            self._buckets[b_idx].append(item)
            self._maxes[b_idx] = item
        else:
            bucket = self._buckets[b_idx]
            pos = bisect_left(bucket, key)
            bucket.insert(pos, item)

        if len(self._buckets[b_idx]) > self._BUCKET_LIMIT:
            mid = self._BUCKET_LIMIT // 2
            right = self._buckets[b_idx][mid:]
            del self._buckets[b_idx][mid:]
            self._maxes[b_idx] = self._buckets[b_idx][-1]
            self._buckets.insert(b_idx + 1, right)
            self._maxes.insert(b_idx + 1, right[-1])

    def _remove(self, score: int, seq: int) -> None:
        key = (-score, seq)
        b_idx = bisect_left(self._maxes, key)
        bucket = self._buckets[b_idx]
        pos = bisect_left(bucket, key)
        bucket.pop(pos)

        if not bucket:
            del self._buckets[b_idx]
            del self._maxes[b_idx]
        elif pos == len(bucket):
            self._maxes[b_idx] = bucket[-1]

    def submit(self, player: object, score: int) -> bool:
        entry = self._players.get(player)
        if entry is not None:
            old_score, old_seq = entry
            if score <= old_score:
                return False
            self._remove(old_score, old_seq)

        seq = self._seq
        self._seq += 1
        self._players[player] = (score, seq)
        self._insert((-score, seq, player))
        return True

    def best(self, player: object) -> int:
        return self._players[player][0]

    def rank(self, player: object) -> int:
        score = self._players[player][0]
        key = (-score, -1)
        b_idx = bisect_left(self._maxes, key)
        higher = sum(len(self._buckets[i]) for i in range(b_idx))
        if b_idx < len(self._buckets):
            higher += bisect_left(self._buckets[b_idx], key)
        return 1 + higher

    def top(self, k: int) -> list[tuple[object, int]]:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []

        result: list[tuple[object, int]] = []
        for bucket in self._buckets:
            for neg_score, _, player in bucket:
                result.append((player, -neg_score))
                if len(result) == k:
                    return result
        return result

    def player_count(self) -> int:
        return len(self._players)

