class MergeLedger:
    """Disjoint-set structure supporting per-component sizes/sums,
    element value updates, element additions, and LIFO undo of merges."""

    def __init__(self) -> None:
        self._parent: dict[Any, Any] = {}
        self._size: dict[Any, int] = {}
        self._sum_val: dict[Any, Any] = {}
        self._history: list[tuple[Any, Any]] = []
        self._components: int = 0

    def _find(self, x: Any) -> Any:
        parent = self._parent
        curr = parent[x]  # raises KeyError if x is unknown
        while curr != parent[curr]:
            curr = parent[curr]
        return curr

    def add(self, x: Any, value: Any = 0) -> None:
        if x in self._parent:
            raise ValueError(f"Element {x!r} already exists")
        self._parent[x] = x
        self._size[x] = 1
        self._sum_val[x] = value
        self._components += 1

    def merge(self, a: Any, b: Any) -> bool:
        ra = self._find(a)
        rb = self._find(b)
        if ra == rb:
            return False
        if self._size[ra] < self._size[rb]:
            ra, rb = rb, ra
        self._parent[rb] = ra
        self._size[ra] += self._size[rb]
        self._sum_val[ra] += self._sum_val[rb]
        self._history.append((ra, rb))
        self._components -= 1
        return True

    def same(self, a: Any, b: Any) -> bool:
        return self._find(a) == self._find(b)

    def component_size(self, x: Any) -> int:
        return self._size[self._find(x)]

    def component_value(self, x: Any) -> Any:
        return self._sum_val[self._find(x)]

    def add_value(self, x: Any, delta: Any) -> None:
        parent = self._parent
        if x not in parent:
            raise KeyError(x)
        sum_val = self._sum_val
        curr = x
        while True:
            sum_val[curr] += delta
            p = parent[curr]
            if p == curr:
                break
            curr = p

    def components(self) -> int:
        return self._components

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("No merges to undo")
        ra, rb = self._history.pop()
        self._parent[rb] = rb
        self._size[ra] -= self._size[rb]
        self._sum_val[ra] -= self._sum_val[rb]
        self._components += 1

