from typing import Generic, Hashable, TypeVar

T = TypeVar("T", bound=Hashable)


class TaskScheduler(Generic[T]):
    """Priority queue of unique task IDs supporting reprioritization and cancellation.

    Higher integer priorities are served first; ties are broken by FIFO order
    of original submission.
    """

    def __init__(self) -> None:
        # task_id -> (priority, submit_seq, entry_id)
        self._active: dict[T, tuple[int, int, int]] = {}
        # min-heap of (-priority, submit_seq, entry_id, task_id)
        self._heap: list[tuple[int, int, int, T]] = []
        self._seq: int = 0
        self._entry_id: int = 0

    def submit(self, task_id: T, priority: int) -> None:
        if task_id in self._active:
            raise ValueError(f"Task {task_id!r} is already active")
        seq = self._seq
        self._seq += 1
        eid = self._entry_id
        self._entry_id += 1
        self._active[task_id] = (priority, seq, eid)
        heapq.heappush(self._heap, (-priority, seq, eid, task_id))

    def reprioritize(self, task_id: T, priority: int) -> None:
        entry = self._active.get(task_id)
        if entry is None:
            raise KeyError(task_id)
        old_priority, seq, _ = entry
        if old_priority == priority:
            return
        eid = self._entry_id
        self._entry_id += 1
        self._active[task_id] = (priority, seq, eid)
        heapq.heappush(self._heap, (-priority, seq, eid, task_id))
        self._maybe_compact()

    def cancel(self, task_id: T) -> None:
        if task_id not in self._active:
            raise KeyError(task_id)
        del self._active[task_id]
        self._maybe_compact()

    def pop(self) -> T:
        if not self._active:
            raise IndexError("pop from an empty TaskScheduler")
        self._discard_stale_top()
        _, _, _, task_id = heapq.heappop(self._heap)
        del self._active[task_id]
        if not self._active:
            self._heap.clear()
        return task_id

    def peek(self) -> T:
        if not self._active:
            raise IndexError("peek from an empty TaskScheduler")
        self._discard_stale_top()
        return self._heap[0][3]

    def priority_of(self, task_id: T) -> int:
        entry = self._active.get(task_id)
        if entry is None:
            raise KeyError(task_id)
        return entry[0]

    def __len__(self) -> int:
        return len(self._active)

    def _discard_stale_top(self) -> None:
        while self._heap:
            _, _, eid, task_id = self._heap[0]
            cur = self._active.get(task_id)
            if cur is not None and cur[2] == eid:
                return
            heapq.heappop(self._heap)

    def _maybe_compact(self) -> None:
        if not self._active:
            self._heap.clear()
        elif len(self._heap) > max(1024, 2 * len(self._active)):
            self._heap = [
                (-prio, seq, eid, tid)
                for tid, (prio, seq, eid) in self._active.items()
            ]
            heapq.heapify(self._heap)

