class UndoStack:
    def __init__(self) -> None:
        self._data: list[Any] = []
        self._history: list[tuple[str, Any]] = []

    def push(self, x: Any) -> None:
        self._data.append(x)
        self._history.append(("push", x))

    def pop(self) -> Any:
        value = self._data.pop()  # raises IndexError if empty, before touching history
        self._history.append(("pop", value))
        return value

    def peek(self) -> Any:
        return self._data[-1]  # raises IndexError if empty

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("Nothing to undo")
        op, value = self._history.pop()
        if op == "push":
            self._data.pop()
        elif op == "pop":
            self._data.append(value)

    def __len__(self) -> int:
        return len(self._data)

