class VersionedKV:
    """A key-value store supporting commit snapshots, point-in-time reads, and rollback."""

    def __init__(self) -> None:
        self._working: dict[Hashable, Any] = {}
        # Index 0 represents the initial empty state; indices 1..N are committed snapshots.
        self._snapshots: list[dict[Hashable, Any]] = [{}]

    def set(self, key: Hashable, value: Any) -> None:
        """Write key-value pair to the working state."""
        self._working[key] = value

    def delete(self, key: Hashable) -> None:
        """Remove key from the working state, or raise KeyError if absent."""
        del self._working[key]

    def get(self, key: Hashable) -> Any:
        """Read key from the working state, or raise KeyError if absent."""
        return self._working[key]

    def has(self, key: Hashable) -> bool:
        """Return whether key is present in the working state."""
        return key in self._working

    def commit(self) -> int:
        """Snapshot the working state and return the new version number."""
        self._snapshots.append(self._working.copy())
        return self.latest()

    def get_at(self, key: Hashable, version: int) -> Any:
        """Return key's value at snapshot `version`."""
        if isinstance(version, bool) or not isinstance(version, int) or not (1 <= version <= self.latest()):
            raise ValueError(f"Invalid version {version!r}; expected 1 <= version <= {self.latest()}")
        return self._snapshots[version][key]

    def rollback(self, version: int) -> None:
        """Replace the working state with a copy of snapshot `version`."""
        if isinstance(version, bool) or not isinstance(version, int) or not (0 <= version <= self.latest()):
            raise ValueError(f"Invalid version {version!r}; expected 0 <= version <= {self.latest()}")
        self._working = self._snapshots[version].copy()

    def latest(self) -> int:
        """Return the number of commits so far (0 if none)."""
        return len(self._snapshots) - 1

import unicodedata

_COMBINING_CATEGORIES = frozenset(("Mn", "Mc", "Me"))


def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be non-negative")
    if width == 0 or not s:
        return ""

    units = 0
    for i, ch in enumerate(s):
        if i == 0 or unicodedata.category(ch) not in _COMBINING_CATEGORIES:
            if units == width:
                return s[:i]
            units += 1

    return s

def kth_root_floor(n: int, k: int) -> int:
    """Return the largest integer r >= 0 such that r ** k <= n."""
    if n < 0 or k < 1:
        raise ValueError("n must be >= 0 and k must be >= 1")
    if n < 2 or k == 1:
        return n
    if k >= n.bit_length():
        return 1

    # Initial upper bound x = 2 ** ceil(n.bit_length() / k) > floor(n ** (1 / k))
    x = 1 << ((n.bit_length() + k - 1) // k)
    k1 = k - 1
    while True:
        y = (k1 * x + n // (x ** k1)) // k
        if y >= x:
            return x
        x = y

