    w_fracs = []
    for w in weights:
        if w < 0:
            raise ValueError("weights must be non-negative")
        w_fracs.append(Fraction(w))

    total_weight = sum(w_fracs)
    if total_weight == 0:
        raise ValueError("sum of weights must be > 0")

    shares = []
    remainders = []
    for w in w_fracs:
        quota = total * w / total_weight
        floor_val = quota.numerator // quota.denominator
        shares.append(floor_val)
        remainders.append(quota - floor_val)

    leftover = total - sum(shares)
    order = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
    for i in order[:leftover]:
        shares[i] += 1

    return shares

from collections import deque
from collections.abc import Iterator


def round_robin(iterables: list) -> Iterator:
    iterators = deque(iter(it) for it in iterables)
    while iterators:
        it = iterators.popleft()
        try:
            value = next(it)
        except StopIteration:
            continue
        iterators.append(it)
        yield value

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if not values:
        raise ValueError("values and weights must not be empty")

    pairs = []
    total_weight = 0.0
    for v, w in zip(values, weights):
        if w < 0:
            raise ValueError("weights must be non-negative")
        if w > 0:
            pairs.append((v, w))
            total_weight += w

    if total_weight <= 0:
        raise ValueError("sum of weights must be positive")

    pairs.sort(key=lambda pair: pair[0])
    threshold = total_weight / 2.0 - 1e-9

    cumulative = 0.0
    for v, w in pairs:
        cumulative += w
        if cumulative >= threshold:
            return float(v)

    return float(pairs[-1][0])

import math


def vector_norm(v: list[float]) -> float:
    if not v:
        return 0.0

    isfinite = math.isfinite
    max_abs = 0.0
    for x in v:
        if not isfinite(x):
            raise ValueError("vector entries must be finite")
        ax = abs(x)
        if ax > max_abs:
            max_abs = ax

    if max_abs == 0.0:
        return 0.0

    _, exp = math.frexp(max_abs)
    shift = -exp
    ldexp = math.ldexp
    sum_sq = math.fsum((y := ldexp(x, shift)) * y for x in v)

    try:
        return ldexp(math.sqrt(sum_sq), exp)
    except OverflowError:
        return math.inf

from heapq import heappush, heapreplace


def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError("cap must be at least 1")
    if not jobs:
        return 0

    heap: list[int] = []
    heap_len = 0
    for d, p in sorted(jobs):
        limit = d * cap
        if heap_len < limit:
            heappush(heap, p)
            heap_len += 1
        elif p > heap[0]:
            heapreplace(heap, p)

    return sum(heap)

from itertools import islice


def count_pulses(deltas: list[int], k: int, lo: int, hi: int) -> int:
    n = len(deltas)
    if not (1 <= lo <= hi <= n):
        raise ValueError("Require 1 <= lo <= hi <= len(deltas)")

    if k == 1:
        m = hi - lo + 1
        return m * ((n - lo + 1) + (n - hi + 1)) // 2

    # Compute prefix sums modulo k: R[j] = sum(deltas[:j]) % k
    r = 0
    R = [0]
    append = R.append
    for x in deltas:
        r = (r + x) % k
        append(r)

    ans = 0
    if k <= n and k <= 2_000_000:
        counts = [0] * k
        for r_in, r_q in zip(islice(R, 0, hi - lo + 1), islice(R, lo, hi + 1)):
            counts[r_in] += 1
            ans += counts[r_q]

        for r_in, r_out, r_q in zip(
            islice(R, hi + 1 - lo, n + 1 - lo),
            islice(R, 0, n - hi),
            islice(R, hi + 1, None),
        ):
            counts[r_in] += 1
            counts[r_out] -= 1
            ans += counts[r_q]
    else:
        counts_dict: dict[int, int] = {}
        counts_get = counts_dict.get
        for r_in, r_q in zip(islice(R, 0, hi - lo + 1), islice(R, lo, hi + 1)):
            counts_dict[r_in] = counts_get(r_in, 0) + 1
            ans += counts_get(r_q, 0)

        for r_in, r_out, r_q in zip(
            islice(R, hi + 1 - lo, n + 1 - lo),
            islice(R, 0, n - hi),
            islice(R, hi + 1, None),
        ):
            counts_dict[r_in] = counts_get(r_in, 0) + 1
            c = counts_dict[r_out]
            if c == 1:
                del counts_dict[r_out]
            else:
                counts_dict[r_out] = c - 1
            ans += counts_get(r_q, 0)

    return ans

from operator import mul


def count_locked_pairs(values: list[int], m: int) -> int:
    if m < 1:
        raise ValueError("m must be at least 1")

    n = len(values)
    if n < 2:
        return 0

    mod = m << 1 if (m & 1) else m
    half = mod >> 1

    # Use a dict when values is sparse relative to mod, and a flat list otherwise.
    if (n << 2) < mod:
        counts: dict[int, int] = {}
        get = counts.get
        for v in values:
            r = v % mod
            counts[r] = get(r, 0) + 1

        c0 = get(0, 0)
        ch = get(half, 0)
        ans = (c0 * (c0 - 1) + ch * (ch - 1)) >> 1
        for r, c in counts.items():
            if 0 < r < half:
                ans += c * get(mod - r, 0)
        return ans

    cnt = [0] * mod
    for v in values:
        cnt[v % mod] += 1

    c0 = cnt[0]
    ch = cnt[half]
    ans = (c0 * (c0 - 1) + ch * (ch - 1)) >> 1
    if half > 1:
        ans += sum(map(mul, cnt[1:half], cnt[-1:half:-1]))
    return ans

def recurring_counts(data: list[int], queries: list[tuple[int, int]]) -> list[int]:
    n = len(data)
    q = len(queries)
    ans = [0] * q
    if n == 0 or q == 0:
        return ans

    buckets: list[list[tuple[int, int]]] = [[] for _ in range(n + 1)]
    for qi, (l, r) in enumerate(queries):
        if l < r:
            buckets[r].append((l, qi))

    bit = [0] * (n + 1)
    last1: dict[int, int] = {}
    last2: dict[int, int] = {}
    last1_get = last1.get
    last2_get = last2.get
    active = 0

    for i, v in enumerate(data):
        p1 = last1_get(v, -1)
        if p1 != -1:
            p2 = last2_get(v, -1)
            if p2 != -1:
                idx = p2 + 1
                while idx <= n:
                    bit[idx] -= 1
                    idx += idx & -idx
            else:
                active += 1
            last2[v] = p1
            idx = p1 + 1
            while idx <= n:
                bit[idx] += 1
                idx += idx & -idx
        last1[v] = i

        q_list = buckets[i + 1]
        if q_list:
            for l, qi in q_list:
                s = 0
                idx = l
                while idx > 0:
                    s += bit[idx]
                    idx -= idx & -idx
                ans[qi] = active - s

    return ans

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    summary = {}

    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"Invalid record at row {i}: expected a 3-element tuple")

        category, amount, refunded = row

        if not isinstance(category, str) or len(category) == 0:
            raise ValueError(f"Invalid category at row {i}: must be a non-empty str")

        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"Invalid amount at row {i}: must be an int or float")

        if amount < 0:
            raise ValueError(f"Invalid amount at row {i}: must be >= 0")

        if not isinstance(refunded, bool):
            raise TypeError(f"Invalid refunded flag at row {i}: must be a bool")

        amount_float = float(amount)

        if category not in summary:
            summary[category] = {
                "count": 1,
                "gross": amount_float,
                "net": 0.0 if refunded else amount_float,
                "largest": amount_float,
            }
        else:
            entry = summary[category]
            entry["count"] += 1
            entry["gross"] += amount_float
            if not refunded:
                entry["net"] += amount_float
            if amount_float > entry["largest"]:
                entry["largest"] = amount_float

    return summary

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    if (
        isinstance(low, bool)
        or not isinstance(low, (int, float))
        or isinstance(high, bool)
        or not isinstance(high, (int, float))
    ):
        raise TypeError("bounds must be numbers")

    if low > high:
        raise ValueError("low must not exceed high")

    result = []
    for i, item in enumerate(values):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(f"invalid element at index {i}")
        if item < low:
            result.append(low)
        elif item > high:
            result.append(high)
        else:
            result.append(item)

    return result

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    stack = [iter(nested)]

    while stack:
        try:
            elem = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue

        if isinstance(elem, list) and len(stack) <= max_depth:
            stack.append(iter(elem))
        else:
            result.append(elem)

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")

    if not text or not text.strip():
        raise ValueError("empty duration")

    units = {"h": (0, 3600), "m": (1, 60), "s": (2, 1)}
    total = 0
    min_stage = 0
    i = 0
    n = len(text)

    while i < n:
        start = i
        while i < n and "0" <= text[i] <= "9":
            i += 1

        if i == start or i == n:
            raise ValueError("malformed duration")

        unit = text[i]
        if unit not in units:
            raise ValueError("malformed duration")

        stage, multiplier = units[unit]
        if stage < min_stage:
            raise ValueError("malformed duration")

        value = int(text[start:i])
        total += value * multiplier
        min_stage = stage + 1
        i += 1

    return total

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    name_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_"
    out = []
    n = len(template)
    i = 0

    while i < n:
        ch = template[i]
        if ch == "{":
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
            else:
                p = i
                j = i + 1
                while j < n:
                    c = template[j]
                    if c == "}":
                        break
                    if c in name_chars:
                        j += 1
                    else:
                        raise ValueError("invalid placeholder at position " + str(p))
                if j == n:
                    raise ValueError("unclosed placeholder at position " + str(p))
                if j == p + 1:
                    raise ValueError("empty placeholder at position " + str(p))
                name = template[p + 1 : j]
                out.append(str(context[name]))
                i = j + 1
        elif ch == "}":
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
            else:
                raise ValueError("stray '}' at position " + str(i))
        else:
            out.append(ch)
            i += 1

    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if tokens == []:
        raise ValueError("empty expression")

    stack = []
    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError(f"expected str at token {i}")

        if tok in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            elif tok == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                quotient = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    quotient = -quotient
                stack.append(quotient)
        else:
            if not tok:
                raise ValueError(f"unknown token at token {i}")
            digits = tok[1:] if tok[0] in "+-" else tok
            if not digits or not all("0" <= ch <= "9" for ch in digits):
                raise ValueError(f"unknown token at token {i}")
            stack.append(int(tok))

    if len(stack) > 1:
        raise ValueError("leftover operands on stack")
    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    if "" in segments:
        raise ValueError("path contains an empty segment")

    def _traverse(node, idx):
        if idx == len(segments):
            return node

        seg = segments[idx]

        if isinstance(node, dict):
            if seg not in node:
                raise KeyError(seg)
            return _traverse(node[seg], idx + 1)

        if isinstance(node, list):
            digits = seg[1:] if seg.startswith("-") else seg
            if not (digits.isascii() and digits.isdigit()):
                raise ValueError(f"invalid index: {seg!r}")
            index = int(seg)
            try:
                next_node = node[index]
            except IndexError:
                raise IndexError(f"list index {seg} out of range")
            return _traverse(next_node, idx + 1)

        raise TypeError(
            f"cannot descend into {type(node).__name__} with segment {seg!r}"
        )

    return _traverse(data, 0)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    if k == 0 or not items:
        return []

    counts = {}
    for item in items:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1

    pairs = []
    for value, count in counts.items():
        pairs.append((value, count))

    def rank_pairs(seq):
        if len(seq) <= 1:
            return seq
        mid = len(seq) // 2
        left = rank_pairs(seq[:mid])
        right = rank_pairs(seq[mid:])
        merged = []
        i = 0
        j = 0
        while i < len(left) and j < len(right):
            if left[i][1] >= right[j][1]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
        while i < len(left):
            merged.append(left[i])
            i += 1
        while j < len(right):
            merged.append(right[j])
            j += 1
        return merged

    ranked = rank_pairs(pairs)
    return ranked[:k]
